def href(lang,page):return f'/{lang}/'+('' if page=='index' else page+'.html')
def button(lang,page,text,secondary=False):return f'<a class="button {"outline" if secondary else ""}" href="{href(lang,page)}">{text}{arrow}</a>'
def header(lang,page):
 c=copy[lang];other='en' if lang=='de' else 'de'
 nav=''.join(f'<a href="{href(lang,p)}"'+(' aria-current="page"' if p==page else '')+f'>{label}</a>' for p,label in zip(navpages,c['nav']))
 return f'''<a class="skip" href="#main">{'Zum Inhalt' if lang=='de' else 'Skip to content'}</a><header class="header"><a class="brand" href="{href(lang,'index')}" aria-label="Villa Laubach — {c['home']}"><svg viewBox="0 0 44 42" aria-hidden="true"><path d="M4 20 22 5l18 15M10 17v20h24V17M18 37V25h8v12M18 16h8"/></svg><span>Villa Laubach<small>EIFEL & MOSEL</small></span></a><nav class="desktop-nav" aria-label="{'Hauptnavigation' if lang=='de' else 'Main navigation'}">{nav}</nav><div class="header-actions"><div class="languages"><a lang="de" href="{href('de',page)}" {'aria-current="true"' if lang=='de' else ''}>DE</a><span>/</span><a lang="en" href="{href('en',page)}" {'aria-current="true"' if lang=='en' else ''}>EN</a></div><a class="nav-cta" href="{href(lang,'stay')}">{c['cta']} {arrow}</a><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-nav" aria-label="{'Menü' if lang=='de' else 'Menu'}"><span></span><span></span></button></div><nav id="mobile-nav" class="mobile-nav" hidden>{nav}<a href="{href(lang,'stay')}">{c['cta']}</a></nav></header>'''
def footer(lang):
 c=copy[lang]
 return f'''<footer><div class="footer-main"><div><a class="footer-brand" href="{href(lang,'index')}">Villa Laubach<span>EIFEL & MOSEL</span></a><p>{c['footer']}</p></div><div><span class="eyebrow">{'HIER FINDEN SIE UNS' if lang=='de' else 'FIND US HERE'}</span><p>Hohlweg 2<br>56759 Laubach<br>{'Rheinland-Pfalz, Deutschland' if lang=='de' else 'Rhineland-Palatinate, Germany'}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Hohlweg+2+56759+Laubach" target="_blank" rel="noopener noreferrer">{'Route planen' if lang=='de' else 'Get directions'} {arrow}</a></div><div class="footer-links">{''.join(f'<a href="{href(lang,p)}">{label}</a>' for p,label in zip(navpages,c['nav']))}<a href="{href(lang,'stay')}">{c['cta']}</a></div></div><div class="footer-bottom"><span>© Villa Laubach · {c['preview']}</span><div>{''.join(f'<a href="{href(lang,p)}">{c[k]}</a>' for p,k in [('credits','credit'),('legal','legal'),('privacy','privacy')])}</div></div></footer>'''
def closing(lang):
 c=copy[lang];return f'<section class="closing"><span class="eyebrow">VILLA LAUBACH</span><h2>{c["stay"]}</h2><p>{c["staytext"]}</p>{button(lang,"stay",c["cta"])}</section>'
def intro(lang,eyebrow,title,text):return f'<section class="page-intro wrap"><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></section>'

