def home(lang):
 c=copy[lang]
 return f'''<section class="hero"><div class="hero-copy"><span class="eyebrow">{c['location']}</span><h1>{c['hero']}</h1><p>{c['intro']}</p>{button(lang,'house',c['explore'])}<div class="hero-foot"><span class="line"></span>{c['scroll']}</div></div><div class="hero-image">{img('house',lang,eager=True)}<span class="image-caption">{'Das ehemalige Schulhaus in Laubach' if lang=='de' else 'The former schoolhouse in Laubach'}</span><div class="hero-seal"><span>VILLA<br>LAUBACH</span><small>1842 / ~1900</small></div></div></section>
<section class="facts wrap"><div><b>8</b><span>{c['guests']}</span></div><div><b>4</b><span>{c['bed']}</span></div><div><b class="symbol">⌂</b><span>{c['whole']}</span></div><div><b class="symbol">☼</b><span>{c['terrace']}</span></div></section>
<section class="story-split wrap"><div class="story-images">{img('stairs',lang)}{img('detail',lang,'detail-photo')}<span class="vertical-label">EIN HAUS MIT GESCHICHTE / A HOUSE WITH A STORY</span></div><div class="section-copy"><span class="eyebrow">{'EIN NEUES KAPITEL' if lang=='de' else 'A NEW CHAPTER'}</span><h2>{c['story']}</h2><p>{c['storytext']}</p><a class="text-link" href="{href(lang,'story')}">{c['storylink']} {arrow}</a><small class="history-note">{'* Ältester Gebäudeteil laut Denkmalverzeichnis: 1842; weiterer Teil um 1900.' if lang=='de' else '* Heritage register: oldest building section 1842; another section around 1900.'}</small></div></section>
<section class="living-section"><div class="wrap section-heading"><div><span class="eyebrow">{'DAS HAUS' if lang=='de' else 'THE HOUSE'}</span><h2>{c['rooms']}</h2></div><p>{c['roomstext']}</p></div><div class="living-grid wrap"><a href="{href(lang,'house')}">{img('living',lang)}<span>{'Zusammensein' if lang=='de' else 'Time together'} {arrow}</span></a><a href="{href(lang,'house')}">{img('bedroom',lang)}<span>{'Zur Ruhe kommen' if lang=='de' else 'Rest and unwind'} {arrow}</span></a><a href="{href(lang,'house')}">{img('terrace',lang)}<span>{'Draußen genießen' if lang=='de' else 'Enjoy the outdoors'} {arrow}</span></a></div></section>
<section class="region-section wrap"><div class="section-heading"><div><span class="eyebrow">EIFEL & MOSEL</span><h2>{c['region']}</h2></div><div><p>{c['regiontext']}</p><a class="text-link" href="{href(lang,'explore')}">{c['regionlink']} {arrow}</a></div></div>{cards(lang)}</section>
<section class="wide-photo">{img('mosel',lang)}<div><span>MOSELSCHLEIFE BEI BREMM</span><p>{'Die Freiheit, den Tag<br>einfach auf sich zukommen zu lassen.' if lang=='de' else 'The freedom to let<br>the day unfold.'}</p></div></section>{visual_story(lang)}{closing(lang)}'''

def house(lang):
 de=lang=='de';c=copy[lang]
 title='Ein Haus für<br><em>Ihre gemeinsame Zeit.</em>' if de else 'A place for<br><em>time together.</em>'
 text='Vier Schlafzimmer, ein großzügiger Wohnbereich und Raum für die kleinen Rituale des Urlaubs.' if de else 'Four bedrooms, a spacious living area and room for the little rituals of a holiday.'
 blocks=[('living','Zusammenkommen','Come together','Lange Gespräche, ein gemeinsames Essen und Zeit ohne Eile. Der Wohnbereich gibt Ihren Tagen einen gemeinsamen Mittelpunkt.','Long conversations, a shared meal and time without hurry. The living area is the centre of your days together.'),('bedroom','Gut zur Ruhe kommen','Room to rest','Vier Schlafzimmer bieten Platz für bis zu acht Gäste. Helle Fenster und individuelle Möbel prägen die Räume.','Four bedrooms accommodate up to eight guests. Bright windows and individual furnishings give the rooms their character.'),('kitchen','Im eigenen Rhythmus','At your own pace','In der Küche beginnt der Tag ganz nach Ihrem Geschmack. Eine Waschmaschine ist ebenfalls vorhanden.','Start the day your own way in the kitchen. A washing machine is also available.'),('terrace','Zeit unter freiem Himmel','Time in the open air','Die Terrasse und die grünen Außenbereiche ergänzen das Haus um Orte zum Sitzen und Durchatmen.','The terrace and green outdoor spaces offer places to sit and take a breath.')]
 out=intro(lang,c['nav'][0],title,text)
 out+='<div class="wrap room-blocks">'+''.join(f'<section class="room-block">{img(k,lang)}<div><span class="eyebrow">VILLA LAUBACH / 0{i+1}</span><h2>{td if de else te}</h2><p>{pd if de else pe}</p></div></section>' for i,(k,td,te,pd,pe) in enumerate(blocks))+'</div>'
 out+=f'''<section class="amenities wrap"><span class="eyebrow">{'GUT ZU WISSEN' if de else 'GOOD TO KNOW'}</span><h2>{'Das gehört dazu.' if de else 'Make yourself at home.'}</h2><div class="amenity-grid">{''.join('<span>'+x+'</span>' for x in (['WLAN','Küche','Waschmaschine','Parkplätze am Haus','Terrasse','TV'] if de else ['Wi-Fi','Kitchen','Washing machine','On-site parking','Terrace','TV']))}</div><div class="info-note"><b>{'Ihre Unterkunft im Haus' if de else 'Your accommodation in the building'}</b><p>{'Die Gästeunterkunft ist eine eigenständige Wohneinheit. Im selben Gebäude gibt es ein separates Loft, in dem sich der Gastgeber zeitweise aufhalten kann. Das Haus verfügt über Treppen. Klären Sie besondere Anforderungen und die Nutzung der Außenbereiche vor Ihrer Buchung direkt mit dem Gastgeber.' if de else 'The guest accommodation is a self-contained unit. A separate loft in the same building may sometimes be occupied by the host. There are stairs in the house. Please discuss any specific needs and the use of outdoor areas directly with the host before booking.'}</p></div></section>{closing(lang)}'''
 return out

def visual_story(lang):
 de=lang=='de'
 items=[('dining','Ein Tisch. Viele Geschichten.','One table. So many stories.'),('swing','Einfach einmal bleiben.','A little longer in the garden.'),('hall','Charakter in jedem Winkel.','Character around every corner.'),('terracedetail','Der Tag darf warten.','Let the day wait.')]
 out=f'<section id="experience" class="visual-story wrap"><span class="eyebrow">{"DAS GEFÜHL, HIER ZU SEIN" if de else "THE FEELING OF BEING HERE"}</span><h2>{"Nicht nur übernachten.<br><em>Hier ankommen.</em>" if de else "More than a place to sleep.<br><em>A place to settle in.</em>"}</h2><div class="story-mosaic">'
 for k,td,te in items:out+=f'<figure>{img(k,lang)}<figcaption>{td if de else te}</figcaption></figure>'
 return out+'</div></section>'

def reading_room(lang):
 de=lang=='de'
 return f'''<section id="reading" class="reading-room wrap"><div class="reading-intro"><span class="eyebrow">{'GESCHICHTEN & LEKTÜRE' if de else 'STORIES & FURTHER READING'}</span><h2>{'Ein Ort, der<br><em>Neugier weckt.</em>' if de else 'A place that<br><em>makes you curious.</em>'}</h2><p>{'Lernen Sie das Dorf und die Geschichte des Hauses aus anderen Perspektiven kennen.' if de else 'Discover the village and the history of the house through other perspectives.'}</p></div><div class="reading-cards"><article><span class="reading-type">COC·PRESSE · 02.09.2026</span><h3>Laubach in der Eifel: Schieferdorf über dem Kaulenbachtal</h3><p>{'Ein Porträt von Laubach, seiner Schieferlandschaft und seinen Kulturdenkmälern. Der Beitrag nennt auch die ehemalige Schule im Hohlweg 2.' if de else 'A portrait of Laubach, its slate landscape and its heritage. The article also mentions the former school at Hohlweg 2.'}</p><a class="text-link" href="https://coc-presse.de/ausflugsziele/laubach-eifel/" target="_blank" rel="noopener noreferrer">{'Artikel lesen (Deutsch)' if de else 'Read the article (German)'} {arrow}</a><small>{'Ein Beitrag über das Dorf, keine Bewertung der Unterkunft.' if de else 'Coverage of the village, rather than a review of the accommodation.'}</small></article><article><span class="reading-type">GDKE · KULTURERBE / HERITAGE</span><h3>{'Die Geschichte ist dokumentiert.' if de else 'A history recorded in the archives.'}</h3><p>{'Das offizielle Denkmalverzeichnis datiert den älteren Teil der ehemaligen Schule auf 1842 und einen weiteren Gebäudeteil auf die Zeit um 1900.' if de else 'The official heritage register dates the older part of the former school to 1842, with a further section dating from around 1900.'}</p><a class="text-link" href="https://gdke.rlp.de/fileadmin/gdke/Service/Cochem-Zell_2026_04_22.pdf" target="_blank" rel="noopener noreferrer">{'Denkmalverzeichnis · Seite 47' if de else 'View the heritage register · page 47'} {arrow}</a></article></div></section>'''

def story(lang):
 de=lang=='de';c=copy[lang]
 out=intro(lang,'UNSERE GESCHICHTE' if de else 'OUR STORY','Alte Mauern.<br><em>Neue Erinnerungen.</em>' if de else 'Old walls.<br><em>New memories.</em>','Ein ehemaliges Schulhaus, ein Ort mit Charakter und eine neue Art, hier Zeit zu verbringen.' if de else 'A former schoolhouse, a place with character and a new way to spend time here.')
 out+=f'<div class="story-banner wrap">{img("detail",lang,eager=True)}<div class="story-quote">“<p>{"Manche Orte erzählen ihre Geschichte ganz leise." if de else "Some places tell their story quietly."}</p></div></div>'
 out+=f'''<section class="article-copy wrap"><span class="eyebrow">HOHLWEG 2 · LAUBACH</span><h2>{'Vom Schulhaus<br><em>zum Urlaubszuhause.</em>' if de else 'From schoolhouse<br><em>to holiday home.</em>'}</h2><p>{'Das offizielle Denkmalverzeichnis führt das Gebäude im Hohlweg 2 als ehemalige Schule. Der traufständige Gebäudeteil wird auf 1842 datiert, der giebelständige Teil auf die Zeit um 1900. Es ist die Geschichte eines Hauses, das sich über Generationen verändert hat.' if de else 'The official heritage register records the building at Hohlweg 2 as a former school. Its eaves-facing section is dated to 1842, with the gable-facing section added around 1900. It is the story of a house that has changed over generations.'}</p><p>{'Heute verbindet Villa Laubach diese Vergangenheit mit einem Aufenthalt im eigenen Rhythmus. Historische Details, hohe Fenster und individuelle Möbel geben dem Haus seinen persönlichen Charakter.' if de else 'Today, Villa Laubach connects that past with a stay at your own pace. Historic details, tall windows and individual furnishings give the house its own character.'}</p><a class="source-link" href="https://gdke.rlp.de/fileadmin/gdke/Service/Cochem-Zell_2026_04_22.pdf" target="_blank" rel="noopener noreferrer">{'Quelle: GDKE, Denkmalverzeichnis Cochem-Zell, S. 47' if de else 'Source: GDKE, Cochem-Zell heritage register, p. 47'} {arrow}</a></section>'''
 timeline=[('1455','Laubach wird erstmals urkundlich erwähnt.','The first documented mention of Laubach.'),('1842','Der ältere Teil des Schulhauses entsteht.','The older section of the schoolhouse dates from this year.'),('um 1900' if de else 'c. 1900','Ein weiterer Gebäudeteil ergänzt das Haus.','Another section is added to the building.'),('Heute' if de else 'Today','Ein Ort für Ihre Zeit in der Eifel.','A setting for your time in the Eifel.')]
 out+='<div class="timeline wrap">'+''.join(f'<div><b>{year}</b><p>{td if de else te}</p></div>' for year,td,te in timeline)+'</div>'
 out+=f'<section class="history-region wrap">{img("oldcochem",lang)}<div><span class="eyebrow">{'DIE REGION DAMALS' if de else 'THE REGION IN THE PAST'}</span><h2>{'Geschichten, die<br><em>weiterführen.</em>' if de else 'Stories that<br><em>lead you further.</em>'}</h2><p>{'Auch außerhalb des Hauses begegnen Ihnen Spuren der Vergangenheit: im Kaulenbachtal, in den Fachwerkorten der Eifel und in den alten Städten an der Mosel.' if de else 'Traces of the past continue beyond the house: in the Kaulenbach valley, the timber-framed villages of the Eifel and the old towns along the Moselle.'}</p><small>{'Historische Ansicht von Cochem, 1890–1905. Keine Aufnahme der Villa.' if de else 'Historic view of Cochem, 1890–1905. This is not a photograph of the villa.'}</small></div></section>'+closing(lang)
 return out.replace(closing(lang),visual_story(lang)+reading_room(lang)+closing(lang))

def explore(lang):
 de=lang=='de'
 out=intro(lang,'EIFEL & MOSEL','Draußen wartet<br><em>Ihre nächste Geschichte.</em>' if de else 'Your next story<br><em>starts outside.</em>','Natur, Kultur und ein guter Grund, einen Tag länger zu bleiben. Unsere Ideen für Ihre Zeit rund um Laubach.' if de else 'Nature, culture and a reason to stay another day. A few ideas for your time around Laubach.')
 out+='<section class="wrap explore-cards">'+cards(lang,True)+'</section>'
 out+=f'''<section class="special-trip wrap"><div><span class="eyebrow">{'FÜR MOTORSPORTFANS' if de else 'FOR MOTORSPORT ENTHUSIASTS'}</span><h2>Nürburgring.<br><em>{'Ein Tag voller Energie.' if de else 'A day with a different pace.'}</em></h2><p>{'Von Veranstaltungen bis zu Besucherangeboten: Planen Sie Ihren Tag direkt mit dem Nürburgring. Das passende Programm und die Anreise richten sich nach Ihrem Besuch.' if de else 'From events to visitor experiences: plan your day directly with the Nürburgring. Your programme and arrival arrangements depend on the experience you choose.'}</p><a class="text-link" href="https://www.nuerburgring.de/driving?locale={'de' if de else 'en'}" target="_blank" rel="noopener noreferrer">{'Zum Nürburgring' if de else 'Visit the Nürburgring website'} {arrow}</a></div><div class="number-art"><span>NORDSCHLEIFE</span><strong style="display:block;font:italic 64px Georgia;padding:65px 12px">Nürburgring</strong><small>EIFEL · MOTORSPORT · ENTDECKUNGEN</small></div></section>'''
 out+=f'''<section class="trip-list wrap"><span class="eyebrow">{'NOCH MEHR ERLEBEN' if de else 'MORE TO EXPLORE'}</span><h2>{'Für jeden Tag<br><em>eine andere Idee.</em>' if de else 'A different idea<br><em>for every day.</em>'}</h2>'''
 links=[('Burg Eltz','Eine Burg inmitten des Waldes.','A castle among the trees.','https://burg-eltz.de/'),('Maria Martental','Ein stiller Ort und ein Teil der Geschichte der Region.','A peaceful setting and part of the region’s heritage.','https://www.scj.de/unsere-haeuser/maria-martental'),('Moselrundfahrt' if de else 'Moselle boat trip','Die Landschaft vom Wasser aus entdecken.','Discover the landscape from the water.','https://www.moselrundfahrten.de/fahrten/schiffstouren/rundfahrt/6'),('Weinprobe' if de else 'Wine tasting','Moselweine kennenlernen, auch auf Englisch nach Vereinbarung.','Discover Moselle wines, with English tastings by arrangement.','https://haxel.de/?page_id=49'),('Klotti / Klotten','Ein Ausflug für die Familie, passend zur Saison.','A family day out, according to the season.','https://klotti.de/'),('Lava-Dome','Vulkanismus entdecken – auch eine Idee für Regentage.','Explore the world of volcanoes, including on a rainy day.','https://www.lavadome.de/faq/')]
 out+=''.join(f'<a class="trip-row" href="{u}" target="_blank" rel="noopener noreferrer"><h3>{name}</h3><p>{td if de else te}</p>{arrow}</a>' for name,td,te,u in links)
 out+=f'''<div class="info-note"><b>{'Gut geplant unterwegs' if de else 'Plan your visit'}</b><p>{'Ausflugsziele sind eigenständige Anbieter und nicht Teil der Unterkunft. Bitte prüfen Sie Öffnungszeiten, Wegzustand, Anreise und Buchungsbedingungen direkt beim jeweiligen Anbieter. Die komplette Route Wilde Endert und einige Burgenwege erfordern passende Kondition. An der Wilden Endert sind Brückenschäden gemeldet; der Turm der Löwenburg in Monreal ist laut Betreiber wegen Sanierung geschlossen.' if de else 'Excursions are run by independent operators and are not included with the accommodation. Check opening times, trail conditions, directions and booking terms with each operator. The full Wilde Endert route and some castle paths require suitable fitness. Bridge damage has been reported on the Wilde Endert route; the tower of Monreal’s Löwenburg is closed for renovation according to its operator.'}</p><a href="https://www.eifel.info/touren/wilde-endert" target="_blank" rel="noopener noreferrer">Wilde Endert ↗</a> · <a href="https://kulturerbe-eifel-mosel.de/weitere-monumente/burgruinen-monreal" target="_blank" rel="noopener noreferrer">Monreal ↗</a></div></section>{closing(lang)}'''
 return out

def gallery(lang):
 de=lang=='de'
 out=intro(lang,'VILLA LAUBACH','Ein erster Blick.<br><em>Und viele kleine Details.</em>' if de else 'A first glimpse.<br><em>And the little details.</em>','Lernen Sie das Haus und seine Umgebung in Bildern kennen.' if de else 'Get to know the house and its surroundings through photographs.')
 out+=f'<section class="wrap gallery-section"><div class="filters" role="group" aria-label="{'Bilder filtern' if de else 'Filter photographs'}">'+''.join(f'<button data-filter="{value}" aria-pressed="{str(value=="all").lower()}">{label}</button>' for value,label in [('all','Alle' if de else 'All'),('house','Das Haus' if de else 'The house'),('outdoor','Draußen' if de else 'Outdoors'),('region','Die Region' if de else 'The region')])+'</div><div class="photo-grid">'
 for k,category in [('house','outdoor'),('living','house'),('bedroom','house'),('stairs','house'),('terrace','outdoor'),('kitchen','house'),('bedroom2','house'),('garden','outdoor'),('detail','outdoor'),('dining','house'),('swing','outdoor'),('hall','house'),('wood','house'),('terracedetail','outdoor'),('stove','house'),('village','region'),('valley','region'),('kaulen','region'),('martental','region'),('geierlay','region'),('oldcochem','region'),('monreal','region'),('ulmen','region'),('cochem','region'),('mosel','region')]:
  out+=f'<button class="gallery-item" data-category="{category}" data-image="{k}" aria-label="{copy[lang]["view"]}: {html.escape(images[k][1 if de else 2])}">{img(k,lang)}<span>{images[k][1 if de else 2]} <span aria-hidden="true">+</span></span></button>'
 out+=f'</div><p class="gallery-note">{'Die Aufnahmen der Ausflugsziele zeigen die Region und keine Aussicht vom Haus. Bildnachweise finden Sie im Fußbereich.' if de else 'Excursion photographs show the region, not views from the house. Image credits are linked in the footer.'}</p></section><dialog class="lightbox"><button class="lightbox-close" aria-label="{copy[lang]["close"]}">×</button><button class="lightbox-prev" aria-label="{copy[lang]["prev"]}">←</button><figure><img alt=""><figcaption></figcaption></figure><button class="lightbox-next" aria-label="{copy[lang]["next"]}">→</button></dialog>'
 return out+closing(lang)

def stay(lang):
 de=lang=='de';c=copy[lang]
 out=intro(lang,c['cta'],'Ein paar freie Tage.<br><em>Ein guter Anfang.</em>' if de else 'A few days away.<br><em>A good beginning.</em>','Stellen Sie Ihre Reiseidee zusammen und kontaktieren Sie den Gastgeber über Airbnb.' if de else 'Put your travel plans together and contact the host through Airbnb.')
 out+=f'''<section class="stay-layout wrap"><div class="planner"><span class="eyebrow">01 / {'IHRE REISEIDEE' if de else 'YOUR TRAVEL PLANS'}</span><h2>{'Wann möchten Sie ankommen?' if de else 'When would you like to arrive?'}</h2><form id="stay-form" data-lang="{lang}"><div class="form-row"><label>{'Anreise' if de else 'Arrival'}<input type="date" name="arrival" required></label><label>{'Abreise' if de else 'Departure'}<input type="date" name="departure" required></label></div><div class="form-row"><label>{'Erwachsene' if de else 'Adults'}<select name="adults">{''.join(f'<option value="{i}"'+(' selected' if i==2 else '')+f'>{i}</option>' for i in range(1,9))}</select></label><label>{'Kinder' if de else 'Children'}<select name="children">{''.join(f'<option value="{i}">{i}</option>' for i in range(0,8))}</select></label></div><label>{'Ihre Nachricht oder Fragen' if de else 'Your message or questions'}<textarea name="message" rows="4" placeholder="{'Was ist Ihnen für Ihren Aufenthalt wichtig?' if de else 'What matters most for your stay?'}"></textarea></label><p id="form-error" class="form-error" role="alert"></p><button type="submit" class="button">{'Anfrage vorbereiten' if de else 'Prepare your enquiry'} {arrow}</button><p class="form-hint">{'Hier wird keine Nachricht versendet und keine Verfügbarkeit geprüft. Im nächsten Schritt können Sie Ihren Text kopieren und den Gastgeber über Airbnb kontaktieren.' if de else 'This does not send a message or check availability. In the next step, copy your text and contact the host through Airbnb.'}</p></form><div id="enquiry-result" hidden><span class="eyebrow">02 / {'IHRE NACHRICHT' if de else 'YOUR MESSAGE'}</span><h3>{'Bereit für den Gastgeber.' if de else 'Ready for the host.'}</h3><textarea id="enquiry-text" rows="9" readonly aria-label="{'Vorbereitete Anfrage' if de else 'Prepared enquiry'}"></textarea><button id="copy-enquiry" type="button" class="button outline">{'Text kopieren' if de else 'Copy message'}</button><a class="button" href="{BOOKING}" target="_blank" rel="noopener noreferrer">{'Gastgeber auf Airbnb kontaktieren' if de else 'Contact the host on Airbnb'} {arrow}</a><p id="copy-status" role="status"></p></div></div><aside class="stay-aside">{img('terrace',lang)}<div><span class="eyebrow">{'DIREKT ZUM GASTGEBER' if de else 'DIRECT TO THE HOST'}</span><h3>{'Lieber direkt auf Airbnb?' if de else 'Prefer to go straight to Airbnb?'}</h3><p>{'Die aktuellen Buchungsbedingungen und Angaben zur Verfügbarkeit finden Sie beim Gastgeber auf Airbnb.' if de else 'Find current booking terms and availability information on the host’s Airbnb listing.'}</p><a class="text-link" href="{BOOKING}" target="_blank" rel="noopener noreferrer">{'Villa Laubach auf Airbnb' if de else 'Villa Laubach on Airbnb'} {arrow}</a></div></aside></section>'''
 faqs=[('Ist das gesamte Gebäude exklusiv für Gäste?','Is the entire building exclusive to guests?','Die Gästeunterkunft ist eine abgeschlossene Wohneinheit. Im gleichen Gebäude befindet sich ein separates Loft des Gastgebers. Er kann sich zeitweise dort aufhalten. Fragen zur Nutzung der Außenbereiche klären Sie bitte direkt mit ihm.','The guest accommodation is a self-contained unit. The same building contains a separate loft for the host, who may sometimes stay there. Please ask the host about the use of outdoor areas.'),('Wie viele Gäste können übernachten?','How many guests can stay?','Die Unterkunft wird für bis zu acht Gäste mit vier Schlafzimmern angeboten. Stimmen Sie die passende Bettenaufteilung und die Bedürfnisse von Kindern mit dem Gastgeber ab.','The accommodation is listed for up to eight guests with four bedrooms. Confirm bed arrangements and children’s needs with the host.'),('Welche An- und Abreisezeiten gelten?','What are the check-in and check-out times?','Bitte beachten Sie die Angaben zu Ihrer konkreten Buchung und bestätigen Sie besondere Ankunftswünsche direkt mit dem Gastgeber.','Please follow the terms of your specific booking and confirm any particular arrival needs directly with the host.'),('Ist das Haus barrierefrei?','Is the house step-free?','Im Haus gibt es Treppen. Bitte besprechen Sie Einschränkungen und individuelle Anforderungen vor einer Buchung direkt mit dem Gastgeber.','There are stairs in the house. Please discuss mobility needs and individual requirements with the host before booking.'),('Wie erreiche ich Villa Laubach?','Where is Villa Laubach?','Hohlweg 2, 56759 Laubach, Rheinland-Pfalz. Gemeint ist Laubach in der Eifel. Prüfen Sie die Route zu diesem vollständigen Ziel vor Ihrer Anreise.','Hohlweg 2, 56759 Laubach, Rhineland-Palatinate. This is Laubach in the Eifel. Check your route using the full address before travelling.')]
 out+=f'<section class="faq wrap"><span class="eyebrow">{'VOR IHRER REISE' if de else 'BEFORE YOU TRAVEL'}</span><h2>{'Noch eine Frage?' if de else 'A few things to know.'}</h2>'+''.join(f'<details><summary>{qd if de else qe}<span aria-hidden="true">+</span></summary><p>{ad if de else ae}</p></details>' for qd,qe,ad,ae in faqs)+'</section>'
 return out

def creditpage(lang):
 de=lang=='de';c=copy[lang]
 out=intro(lang,'VILLA LAUBACH',c['credit'],'Fotografien erzählen Geschichten. Hier finden Sie ihre Quellen und Lizenzen.' if de else 'Photographs tell stories. Here are their sources and licences.')
 out+='<section class="wrap legal-copy"><h2>'+('Hausfotografien' if de else 'Property photographs')+'</h2><p>'+('Die Hausaufnahmen stammen aus dem für diese private Vorschau bereitgestellten Bildmaterial. Die Freigabe der Originalrechte für eine öffentliche Veröffentlichung steht noch aus.' if de else 'Property photographs come from material supplied for this private preview. Original image rights still need to be confirmed before public release.')+'</p>'
 for k,(name,_,_) in images.items():
  if name not in credits:continue
  r=credits[name];lic=r['license_url'] or r['source_page']
  out+=f'<article class="credit-row">{img(k,lang)}<div><h3>{images[k][1 if de else 2]}</h3><p>{html.escape(r["artist"])}</p><a href="{html.escape(r["source_page"])}" target="_blank" rel="noopener noreferrer">{html.escape(r["commons_title"])} ↗</a><br><a href="{html.escape(lic)}" target="_blank" rel="noopener noreferrer">{html.escape(r["license"])} ↗</a><p>{"Für das Web skaliert und in WebP konvertiert. Die Darstellung kann einen Ausschnitt zeigen." if de else "Resized and converted to WebP for the web. Displayed images may be cropped."}</p></div></article>'
 return out+'</section>'

def legal(lang,privacy=False):
 de=lang=='de';c=copy[lang];title=c['privacy' if privacy else 'legal']
 text=('Diese Website ist eine private Vorschau und noch kein öffentlich freigegebener Internetauftritt des Unterkunftsbetreibers.' if de else 'This website is a private preview and is not yet a publicly approved website of the accommodation operator.')
 out=intro(lang,'VILLA LAUBACH',title,text)+'<section class="wrap legal-copy">'
 if privacy:
  out+=('<h2>Ihr Reiseentwurf bleibt bei Ihnen.</h2><p>Der Reiseplaner verarbeitet Eingaben nur im Browser. Er sendet sie nicht an den Gastgeber und speichert sie nicht in einer eigenen Datenbank. Erst wenn Sie Text kopieren, wird er nach Ihrer Aktion in die Zwischenablage übernommen.</p><p>Beim Aufruf externer Links gelten die Datenschutzinformationen des jeweiligen Anbieters. Airbnb, Karten und Ausflugsanbieter werden nicht als eingebettete Inhalte geladen. Es werden keine eigenen Analyse- oder Marketingdienste eingesetzt.</p><p>Die endgültigen Angaben zum Verantwortlichen, Hosting und den tatsächlichen Abläufen sind vor einer öffentlichen Freigabe zu vervollständigen. Die Anmeldung für den Zugriff auf diese private Vorschau wird vom Hostinganbieter verwaltet.</p>' if de else '<h2>Your travel draft stays with you.</h2><p>The trip planner processes entries in your browser. It does not send them to the host or store them in its own database. Copying text places it on your clipboard only after your action.</p><p>External links are subject to the privacy information of the respective provider. Airbnb, maps and excursion providers are not embedded. No additional analytics or marketing services are used.</p><p>Final information about the data controller, hosting and actual processes must be completed before public release. Sign-in for this private preview is managed by the hosting provider.</p>')
 else:
  out+=('<h2>Angaben zum Anbieter</h2><p>Die vollständige Identität, ladungsfähige Anschrift und Kontaktangaben des tatsächlichen Betreibers müssen vor einer öffentlichen Freigabe bestätigt und ergänzt werden. Die Unterkunftsadresse allein ersetzt diese Angaben nicht.</p><h2>Unterkunftsadresse</h2><p>Villa Laubach<br>Hohlweg 2<br>56759 Laubach, Rheinland-Pfalz</p><p>Buchungsanfragen können über das verlinkte Airbnb-Inserat an den dortigen Gastgeber gerichtet werden. Diese Vorschau nimmt keine Buchungen entgegen.</p>' if de else '<h2>Operator information</h2><p>The actual operator’s full identity, address and contact details must be confirmed and completed before public release. The property address alone does not replace these details.</p><h2>Property address</h2><p>Villa Laubach<br>Hohlweg 2<br>56759 Laubach, Rhineland-Palatinate</p><p>Booking enquiries can be directed to the host through the linked Airbnb listing. This preview does not accept bookings.</p>')
 return out+'</section>'

for lang in ['de','en']:
 (DIST/lang).mkdir(exist_ok=True)
 for page in pages:
  c=copy[lang]
  content={'index':home,'house':house,'story':story,'explore':explore,'gallery':gallery,'stay':stay,'credits':creditpage,'legal':legal,'privacy':lambda l:legal(l,True)}[page](lang)
  title=(c['title'] if page=='index' else dict(zip(navpages,c['nav'])).get(page,{'stay':c['cta'],'credits':c['credit'],'legal':c['legal'],'privacy':c['privacy']} .get(page,'')))+' | Villa Laubach'
  document=f'''<!doctype html><html lang="{lang}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#35483c"><meta name="robots" content="noindex,nofollow"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(c['desc'])}"><link rel="canonical" href="{ORIGIN}{href(lang,page)}"><link rel="alternate" hreflang="de" href="{ORIGIN}{href('de',page)}"><link rel="alternate" hreflang="en" href="{ORIGIN}{href('en',page)}"><link rel="alternate" hreflang="x-default" href="{ORIGIN}{href('de',page)}"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(c['desc'])}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/house.webp"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"><script src="/site.js" defer></script></head><body>{header(lang,page)}<main id="main">{content}</main>{footer(lang)}</body></html>'''
  (DIST/lang/(page+'.html')).write_text(document,encoding='utf-8')
(DIST/'index.html').write_text('<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta http-equiv="refresh" content="0;url=/de/"><title>Villa Laubach</title></head><body><a href="/de/">Deutsch</a> · <a href="/en/">English</a></body></html>',encoding='utf-8')
(ASSETS/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="10" fill="#35483c"/><path d="M12 30 32 13l20 17M19 26v27h26V26M27 53V37h10v16" fill="none" stroke="#f6f1e7" stroke-width="3"/></svg>',encoding='utf-8')
(DIST/'robots.txt').write_text('User-agent: *\nDisallow: /\n',encoding='utf-8')
(DIST/'_headers').write_text('/*\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: strict-origin-when-cross-origin\n  X-Robots-Tag: noindex, nofollow\n',encoding='utf-8')
print(f'Generated 18 bilingual pages and {len(images)} optimized photographs.')

# GitHub Pages project sites need a repository path prefix.
if BASE_PATH:
 for page in DIST.rglob('*.html'):
  markup=page.read_text(encoding='utf-8')
  markup=re.sub(r'(href|src)="/(?!/)',lambda m:m.group(1)+'="'+BASE_PATH+'/',markup)
  markup=markup.replace('content="0;url=/','content="0;url='+BASE_PATH+'/')
  page.write_text(markup,encoding='utf-8')
(DIST/'.nojekyll').write_text('',encoding='utf-8')
